B=[(-1,6),(0,7),(2,0),(3,5)]; F=[(-1,0),(0,5),(3,-1),(4,1)];
for i,a in enumerate(B):
 for j,b in enumerate(F):
  d=(b[0]-a[0],b[1]-a[1]); common=[(u,v) for u in B for v in F if (v[0]-u[0],v[1]-u[1])==d]
  if len(common)>=2: print(d, common)

pieces={
'A': {'body':{(0,0),(0,2),(1,0),(1,2),(1,1)}, 'ports':{(-1,0),(-1,2)}},
'B': {'body':set([(0,c) for c in range(7)]+[(1,0),(1,6),(2,6),(3,6)]), 'ports':{(-1,6),(0,7),(2,0),(3,5)}},
'3': {'body':set([(0,c) for c in range(5)]+[(1,0),(1,4),(2,4)]+[(3,c) for c in range(2,5)]), 'ports':{(2,0),(3,1),(4,2),(4,4)}},
'4': {'body':set((r,c) for r in range(4) for c in range(5)), 'ports':{(-1,0),(0,5),(3,-1),(4,1)}},
'8': {'body':{(r,c) for r in range(4) for c in [1,4]}|{(3,c) for c in range(6)}, 'ports':{(-1,1),(-1,4),(4,0),(4,5)}},
'9': {'body':{(0,c) for c in range(3)}|{(1,0),(2,0),(2,5)}|{(3,c) for c in range(6)}, 'ports':{(0,3),(1,5),(4,1),(4,4)}},
'5': {'body':{(0,c) for c in range(6)}, 'ports':{(-1,0),(-1,5)}}
}
import itertools
for n1,n2 in itertools.combinations(pieces,2):
 p1,p2=pieces[n1],pieces[n2]
 found=[]
 for dr in range(-15,16):
  for dc in range(-15,16):
   m=set((r+dr,c+dc) for r,c in p1['ports']) & p2['ports']
   if len(m)>=1 and not (set((r+dr,c+dc) for r,c in p1['body']) & p2['body']):
    found.append((len(m),dr,dc,sorted(m)))
 if found:
  print(n1,n2,sorted(found,reverse=True)[:5])

for n1,n2 in itertools.combinations(pieces,2):
 p1,p2=pieces[n1],pieces[n2]; found=[]
 for dr in range(-10,11):
  for dc in range(-10,11):
   m=set((r+dr,c+dc) for r,c in p1['ports']) & p2['ports']
   ov=set((r+dr,c+dc) for r,c in p1['body']) & p2['body']
   if len(m)>=2 and not ov: found.append((len(m),dr,dc, sorted(m)))
 if found: print(n1,n2,found)

origins={'3':(0,0),'A':(5,2),'B':(3,-6),'4':(6,-6),'9':(9,-10),'8':(14,-10),'5':(19,-10)}
colors={'A':1,'B':1,'3':3,'4':4,'9':9,'8':8,'5':5}
all_body={}; all_ports={}
for n,p in pieces.items():
 r0,c0=origins[n]; c0+=10
 for r,c in p['body']:
  q=(r0+r,c0+c)
  if q in all_body: print('BODY OVERLAP', n,q,all_body[q])
  all_body[q]=colors[n]
 for r,c in p['ports']:
  q=(r0+r,c0+c)
  all_ports.setdefault(q,[]).append(n)
print('body cells',len(all_body),'ports',len(all_ports),'max',max(r for r,c in all_body),max(c for r,c in all_body),'min',min(c for r,c in all_body))
print('overlap marker sets',[(k,v) for k,v in all_ports.items() if len(v)>1])
print('markers on bodies',[(q,all_body[q],v) for q,v in all_ports.items() if q in all_body])
out=[[0]*26 for _ in range(26)]
for (r,c),v in all_ports.items():
 if 0<=r<26 and 0<=c<26: out[r][c]=2
for (r,c),col in all_body.items():
 if 0<=r<26 and 0<=c<26: out[r][c]=col
print('\n'.join(' '.join(map(str,row)) for row in out))

# Anchor the four-color rectangle at its original top-left (row 11, col 9).
origins2={'4':(11,9),'B':(8,9),'3':(5,15),'A':(10,17),'9':(14,5),'8':(19,5),'5':(24,5)}
out2=[[0]*26 for _ in range(26)]; body2={}; ports2={}
for n,p in pieces.items():
 r0,c0=origins2[n]
 for r,c in p['body']:
  q=(r0+r,c0+c)
  if q in body2: print('overlap',n,q,body2[q])
  body2[q]=colors[n]
 for r,c in p['ports']:
  ports2.setdefault((r0+r,c0+c),[]).append(n)
print('body outside',[(q,v) for q,v in body2.items() if not (0<=q[0]<26 and 0<=q[1]<26)])
print('ports outside',[(q,v) for q,v in ports2.items() if not (0<=q[0]<26 and 0<=q[1]<26)])
print('paired',[(q,v) for q,v in ports2.items() if len(v)>1])
for q in ports2:
 if q not in body2: out2[q[0]][q[1]]=2
for q,col in body2.items(): out2[q[0]][q[1]]=col
print('\n'.join(' '.join(map(str,row)) for row in out2))
